-- Generated on 2026-02-21 from DEV database iset_intake
-- Source row: iset_runtime_config.id = 58
-- Purpose: publish DEV intake runtime config into TEST without direct DB-to-DB connectivity
-- Encoding approach: JSON is stored as UTF-8 base64 and decoded in SQL (unicode-safe)

SET NAMES utf8mb4;
SET @target_id := 58;
SET @target_scope := 'publish';
SET @target_key := 'workflow.schema.intake';
SET @json_b64 := '';

SET @json_text := CONVERT(FROM_BASE64(@json_b64) USING utf8mb4);

-- Preflight checks
SELECT
  JSON_VALID(@json_text) AS json_valid,
  CHAR_LENGTH(@json_text) AS json_char_len,
  LENGTH(@json_text) AS json_byte_len;

START TRANSACTION;

-- Upsert row 58 in target DB
INSERT INTO iset_runtime_config (id, scope, k, v, updated_at)
VALUES (@target_id, @target_scope, @target_key, CAST(@json_text AS JSON), NOW())
ON DUPLICATE KEY UPDATE
  scope = VALUES(scope),
  k = VALUES(k),
  v = VALUES(v),
  updated_at = NOW();

-- Post-check
SELECT
  id,
  scope,
  k,
  updated_at,
  JSON_UNQUOTE(JSON_EXTRACT(v, '$.meta.checksum')) AS checksum,
  JSON_UNQUOTE(JSON_EXTRACT(v, '$.meta.schemaMeta.generatedAt')) AS generated_at_utc
FROM iset_runtime_config
WHERE id = @target_id;

COMMIT;
